#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin>>t;
    while(t--)
    {
        int n,m;
        cin>>n>>m;
        vector<int>v;
        for(int i=0; i<m; i++)
        {
            int x;
            cin>>x;
            v.push_back(x);
        }
        sort(v.begin(),v.end());
        int x=min(v[0]-1,n-v[m-1]);
        int ans=2*x;
        //cout<<ans<<endl;
        int s=0;
        if(x==v[0]-1)
        {
            //cout<<'a'<<endl;
            for(int i=0; i<m-1; i++)
            {
                
                s=max(v[i+1]-(v[i]+1+x),s);
                
            }
            s=max(n-(v[m-1]),s);
        }
        else{
            //cout<<'b'<<endl;
            for(int i=0; i<m-1; i++)
            {
                s=max(v[i+1]-(v[i]+1+x),s);
            }
            s=max(v[0]-1,s);
            
        }

        
        cout<<s+ans<<endl;
    }
    return 0;
}
